<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { api } from './api'
type Item = { id:number; author_name:string; author_role:string; content:string; created_at:string }
const props = defineProps<{ticketId:number; status:string; canReply:boolean; events?:{to_status:string;remark:string;created_at:string}[]}>()
const entries=ref<Item[]>([]), text=ref(''), busy=ref(false), loading=ref(false), failed=ref(false), offset=ref(0), hasMore=ref(false)
let request=0
let retryKey="", retryContent=""
const history=computed(()=>[...entries.value.map(item=>({key:`message-${item.id}`,time:item.created_at,title:`${item.author_name} · ${item.author_role==='player'?'玩家':'客服'}`,content:item.content})),...(props.events||[]).map((item,i)=>({key:`event-${i}`,time:item.created_at,title:({PENDING:'待处理',ASSIGNED:'已接单',PROCESSING:'处理中',CLOSED:'已完成',RATED:'已评价'} as Record<string,string>)[item.to_status]||item.to_status,content:item.remark}))].sort((a,b)=>a.time.localeCompare(b.time)))
async function load(reset=true){const id=props.ticketId, seq=++request; if(reset)offset.value=0; loading.value=true;failed.value=false;try{const {data}=await api.get(`/tickets/${id}/messages`,{params:{offset:offset.value,limit:50}});if(seq!==request)return;entries.value=reset?data:[...entries.value,...data];hasMore.value=data.length===50}catch{if(seq===request)failed.value=true}finally{if(seq===request)loading.value=false}}
async function send(){const id=props.ticketId, content=text.value.trim();if(!content||busy.value)return;if(!retryKey||retryContent!==content){retryKey=globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`;retryContent=content}const key=retryKey;busy.value=true;try{await api.post(`/tickets/${id}/messages`,{content,request_id:key});if(id===props.ticketId){retryKey='';retryContent='';text.value='';await load()}}catch{if(id===props.ticketId)failed.value=true}finally{busy.value=false}}
watch(()=>props.ticketId,()=>{entries.value=[];text.value='';retryKey='';retryContent='';void load()},{immediate:true})
</script>
<template><section class="ticket-thread"><h3>工单沟通</h3><p v-if="loading">正在加载回复…</p><p v-if="failed" role="alert">操作失败，请检查工单状态后重试。 <button type="button" @click="load()">重试</button></p><p v-if="!loading&&!failed&&!history.length">暂无记录</p><div v-for="entry in history" :key="entry.key" class="thread-entry"><strong>{{entry.title}}</strong><small>{{entry.time.replace('T',' ').slice(0,16)}}</small><p v-if="entry.content">{{entry.content}}</p></div><button v-if="hasMore" type="button" @click="offset+=50;load(false)">查看更多</button><form v-if="canReply && !['CLOSED','RATED'].includes(status)" @submit.prevent="send"><label>回复内容<textarea v-model="text" maxlength="5000" rows="3" required></textarea></label><button type="submit" :disabled="busy || !text.trim()">{{busy?'发送中…':'发送回复'}}</button></form></section></template>
<style scoped>.ticket-thread{margin-top:24px;border-top:1px dashed #aab5ca;padding-top:12px}.thread-entry{border-bottom:1px solid #c9ceda;padding:12px 0;overflow-wrap:anywhere}.thread-entry small{display:block;color:#66738c;margin-top:5px}.thread-entry p{white-space:pre-wrap;line-height:1.6}.ticket-thread form{display:grid;gap:10px}.ticket-thread textarea{width:100%;margin-top:8px}.ticket-thread button{padding:9px 15px;border:1px solid #8090ad;background:#d5efe9;color:#14243d;cursor:pointer}</style>
